// Reports which bindings the Worker sees. Never returns a secret value: only
// whether SECRET_SPIKE is present and the SHA-256 of its value (the value is a
// dummy generated by the spike, compared by hash).
export default {
  async fetch(_req: Request, env: Record<string, unknown>): Promise<Response> {
    const s = env.SECRET_SPIKE;
    let sha256: string | null = null;
    if (typeof s === "string") {
      const d = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s));
      sha256 = [...new Uint8Array(d)].map((b) => b.toString(16).padStart(2, "0")).join("");
    }
    return Response.json({
      code: "v1",
      variant: env.SPIKE_VARIANT ?? null,
      secretPresent: typeof s === "string",
      secretSha256: sha256,
      bindings: Object.keys(env).sort(),
    });
  },
};
